CREATE TABLE account(id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 0, email varchar(254) NOT NULL, password_hash varchar(255) NOT NULL, display_name varchar(100) NOT NULL, role varchar(20) NOT NULL CHECK(role IN ('CUSTOMER','HOST','MANAGER','DISPLAY')), enabled boolean NOT NULL, created_at timestamptz NOT NULL);
CREATE UNIQUE INDEX uq_account_email ON account(lower(email));
CREATE TABLE restaurant(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,name varchar(120) NOT NULL,location varchar(200) NOT NULL,timezone varchar(64) NOT NULL,description varchar(1000),policy_json text NOT NULL,current_session_id uuid,recovery_required boolean NOT NULL,heartbeat_at timestamptz);
CREATE TABLE dining_area(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,restaurant_id uuid NOT NULL REFERENCES restaurant,name varchar(100) NOT NULL,UNIQUE(restaurant_id,name));
CREATE TABLE restaurant_table(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,restaurant_id uuid NOT NULL REFERENCES restaurant,area_id uuid NOT NULL REFERENCES dining_area,number varchar(20) NOT NULL,capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 20),accessible boolean NOT NULL,enabled boolean NOT NULL,status varchar(20) NOT NULL CHECK(status IN('AVAILABLE','ASSIGNED','OCCUPIED','UNAVAILABLE')),created_at timestamptz NOT NULL,UNIQUE(restaurant_id,number));
CREATE TABLE operating_session(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,restaurant_id uuid NOT NULL REFERENCES restaurant,opens_at timestamptz NOT NULL,closes_at timestamptz NOT NULL,status varchar(20) NOT NULL CHECK(status IN('OPEN','CLOSING','CLOSED')),next_sequence bigint NOT NULL,revision bigint NOT NULL,priority_burst integer NOT NULL,policy_json text NOT NULL,CHECK(closes_at>opens_at));
ALTER TABLE restaurant ADD CONSTRAINT fk_current_session FOREIGN KEY(current_session_id) REFERENCES operating_session;
CREATE UNIQUE INDEX uq_open_session ON operating_session(restaurant_id) WHERE status IN('OPEN','CLOSING');
CREATE TABLE waitlist_entry(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,session_id uuid NOT NULL REFERENCES operating_session,customer_id uuid NOT NULL REFERENCES account,token varchar(32) NOT NULL,sequence bigint NOT NULL,party_size integer NOT NULL CHECK(party_size BETWEEN 1 AND 20),preference varchar(100),accessible boolean NOT NULL,status varchar(20) NOT NULL CHECK(status IN('WAITING','ARRIVAL_WINDOW','CHECKED_IN','SNOOZED','CALLED','SEATED','DINING','COMPLETED','CANCELLED','EXPIRED','NO_SHOW')),joined_at timestamptz NOT NULL,fairness_since timestamptz NOT NULL,checked_in_at timestamptz,arrival_window_opened_at timestamptz,arrival_deadline timestamptz,called_at timestamptz,call_deadline timestamptz,snooze_release_at timestamptz,terminal_at timestamptz,snooze_count integer NOT NULL CHECK(snooze_count BETWEEN 0 AND 2),priority boolean NOT NULL,priority_verified_by uuid REFERENCES account,priority_reason varchar(500),table_id uuid REFERENCES restaurant_table,terminal_reason varchar(500),eta_seconds bigint,estimated_start_at timestamptz,computed_at timestamptz,estimate_source varchar(40) NOT NULL,sample_count integer NOT NULL,confidence varchar(20) NOT NULL,assumes_arrival boolean NOT NULL,position integer,
UNIQUE(session_id,sequence),UNIQUE(session_id,token),CHECK(eta_seconds IS NULL OR eta_seconds>=0),CHECK((arrival_window_opened_at IS NULL AND arrival_deadline IS NULL) OR arrival_deadline>arrival_window_opened_at),CHECK(status<>'CALLED' OR (table_id IS NOT NULL AND call_deadline>called_at)),CHECK(status NOT IN('CHECKED_IN','CALLED','SEATED','DINING','COMPLETED') OR checked_in_at IS NOT NULL),CHECK(status NOT IN('COMPLETED','CANCELLED','EXPIRED','NO_SHOW') OR terminal_at IS NOT NULL));
CREATE UNIQUE INDEX uq_active_customer ON waitlist_entry(session_id,customer_id) WHERE status NOT IN('COMPLETED','CANCELLED','EXPIRED','NO_SHOW');
CREATE UNIQUE INDEX uq_table_occupant ON waitlist_entry(table_id) WHERE status IN('CALLED','SEATED','DINING');
CREATE INDEX ix_session_entries ON waitlist_entry(session_id,status,sequence);
CREATE INDEX ix_arrival_due ON waitlist_entry(arrival_deadline) WHERE status='ARRIVAL_WINDOW';
CREATE INDEX ix_call_due ON waitlist_entry(call_deadline) WHERE status='CALLED';
CREATE INDEX ix_snooze_due ON waitlist_entry(snooze_release_at) WHERE status='SNOOZED';
CREATE TABLE dining_visit(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid NOT NULL UNIQUE REFERENCES waitlist_entry,table_id uuid NOT NULL REFERENCES restaurant_table,party_size integer NOT NULL,started_at timestamptz NOT NULL,completed_at timestamptz,duration_seconds bigint,sample_valid boolean NOT NULL,CHECK(completed_at IS NULL OR completed_at>=started_at),CHECK(NOT sample_valid OR duration_seconds>0));
CREATE UNIQUE INDEX uq_table_visit ON dining_visit(table_id) WHERE completed_at IS NULL;
CREATE INDEX ix_recent_samples ON dining_visit(completed_at DESC) WHERE sample_valid;
CREATE TABLE qr_challenge(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,restaurant_id uuid NOT NULL REFERENCES restaurant,digest varchar(64) NOT NULL UNIQUE,issued_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,CHECK(expires_at>issued_at));
CREATE TABLE arrival(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid NOT NULL UNIQUE REFERENCES waitlist_entry,challenge_id uuid REFERENCES qr_challenge,method varchar(20) NOT NULL CHECK(method IN('QR','ASSISTED')),verified_at timestamptz NOT NULL,verified_by uuid REFERENCES account,reason varchar(500),CHECK((method='QR' AND challenge_id IS NOT NULL) OR (method='ASSISTED' AND verified_by IS NOT NULL AND reason IS NOT NULL)));
CREATE TABLE snooze_barrier(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid NOT NULL REFERENCES waitlist_entry,predecessor_id uuid NOT NULL REFERENCES waitlist_entry,snooze_number integer NOT NULL,released_at timestamptz,release_reason varchar(40),UNIQUE(entry_id,predecessor_id,snooze_number),CHECK(entry_id<>predecessor_id));
CREATE TABLE queue_history(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid NOT NULL REFERENCES waitlist_entry,table_id uuid REFERENCES restaurant_table,from_status varchar(20),to_status varchar(20) NOT NULL,action varchar(80) NOT NULL,actor varchar(100) NOT NULL,reason varchar(500),occurred_at timestamptz NOT NULL,revision bigint NOT NULL);
CREATE TABLE audit_event(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid,action varchar(80) NOT NULL,actor varchar(100) NOT NULL,reason varchar(500),occurred_at timestamptz NOT NULL,details text);
CREATE INDEX ix_audit_time ON audit_event(occurred_at DESC);
CREATE TABLE table_history(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,table_id uuid NOT NULL REFERENCES restaurant_table,old_status varchar(20),new_status varchar(20) NOT NULL,enabled boolean NOT NULL,occurred_at timestamptz NOT NULL);
CREATE TABLE outbox_event(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid REFERENCES waitlist_entry,recipient_id uuid NOT NULL REFERENCES account,kind varchar(80) NOT NULL,title varchar(150) NOT NULL,body varchar(1000) NOT NULL,created_at timestamptz NOT NULL,processed_at timestamptz);
CREATE INDEX ix_outbox_pending ON outbox_event(created_at) WHERE processed_at IS NULL;
CREATE TABLE notification(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,event_id uuid NOT NULL UNIQUE REFERENCES outbox_event,recipient_id uuid NOT NULL REFERENCES account,kind varchar(80) NOT NULL,title varchar(150) NOT NULL,body varchar(1000) NOT NULL,created_at timestamptz NOT NULL,read_at timestamptz);
CREATE INDEX ix_notification_owner ON notification(recipient_id,created_at DESC);
CREATE TABLE idempotency_record(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,actor_id uuid NOT NULL REFERENCES account,route varchar(180) NOT NULL,request_key varchar(80) NOT NULL,request_hash varchar(64) NOT NULL,response_json text NOT NULL,created_at timestamptz NOT NULL,UNIQUE(actor_id,route,request_key));
CREATE TABLE feedback(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,entry_id uuid NOT NULL UNIQUE REFERENCES waitlist_entry,customer_id uuid NOT NULL REFERENCES account,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment varchar(1000),created_at timestamptz NOT NULL);
CREATE TABLE spring_session(primary_id char(36) NOT NULL PRIMARY KEY,session_id char(36) NOT NULL,creation_time bigint NOT NULL,last_access_time bigint NOT NULL,max_inactive_interval integer NOT NULL,expiry_time bigint NOT NULL,principal_name varchar(100));
CREATE UNIQUE INDEX spring_session_ix1 ON spring_session(session_id);
CREATE INDEX spring_session_ix2 ON spring_session(expiry_time);
CREATE INDEX spring_session_ix3 ON spring_session(principal_name);
CREATE TABLE spring_session_attributes(session_primary_id char(36) NOT NULL,attribute_name varchar(200) NOT NULL,attribute_bytes bytea NOT NULL,PRIMARY KEY(session_primary_id,attribute_name),CONSTRAINT spring_session_attributes_fk FOREIGN KEY(session_primary_id) REFERENCES spring_session(primary_id) ON DELETE CASCADE);
